    return bin(x).count('1') % 2

def solution(x):
    """Returns the position of the least significant set bit (0-indexed from the right)."""
    return (x & -x).bit_length() - 1 if x != 0 else 0

def solution(x):
    """Returns the number of trailing zeros in the binary representation of x."""
    return (x & -x).bit_length() - 1 if x != 0 else 0
